#include <iostream>
#include <string>

int main() {
    // 1. Default constructor
    std::string s1;
    // 2. C-string constructor
    std::string s2("Hello");
    // 3. Fill constructor: 8 repetitions of 'x'
    std::string s3(8, 'x');
    // 4. Conversion initialization (implicit constructor)
    std::string s4 = "March";
    // 5. Copy constructor
    std::string s5(s2);

    std::cout << "s1 size: " << s1.size() << " | value: '" << s1 << "'\n";
    std::cout << "s2 length: " << s2.length() << " | value: " << s2 << "\n";
    std::cout << "s3 size: " << s3.size() << " | value: " << s3 << "\n";
    std::cout << "s4 size: " << s4.size() << " | value: " << s4 << "\n";
    std::cout << "s5 size: " << s5.size() << " | value: " << s5 << "\n";

    return 0;
}

#include <iostream>
#include <sstream>
#include <string>

int main() {
    // Simulate input stream with a token, a full line, and delimited text
    std::string rawData = "Alpha\nBeta Gamma Delta\nField1,Field2,Field3\n";
    std::istringstream stream(rawData);

    std::string token;
    stream >> token; // Reads up to whitespace
    std::cout << "Operator>>: " << token << "\n";

    std::string line;
    std::getline(stream >> std::ws, line); // Reads full line
    std::cout << "Default getline(): " << line << "\n";

    std::string field;
    std::cout << "Custom delimiter (,):\n";
    while (std::getline(stream, field, ',')) {
        // Basic validation: strip trailing newline if present
        if (!field.empty() && field.back() == '\n') {
            field.pop_back();
        }
        if (!field.empty()) {
            std::cout << "  Token: " << field << "\n";
        }
    }

    return 0;
}

#include <iostream>
#include <string>
#include <stdexcept>

int main() {
    std::string string1("cat");
    std::string string2;
    std::string string3;

    // Assignment
    string2 = string1;
    string3.assign(string1);
    std::cout << "string1: " << string1 << "\nstring2: " << string2
              << "\nstring3: " << string3 << "\n\n";

    // Modify characters using subscript operator []
    string2[0] = string3[2] = 'r';
    std::cout << "After modification of string2 and string3:\n"
              << "string1: " << string1 << "\nstring2: " << string2
              << "\nstring3: ";

    // Demonstrating member function at
    for (size_t i = 0; i < string3.size(); ++i) {
        std::cout << string3.at(i);
    }

    // Concatenation using +, +=, and append
    std::string string4(string1 + "apult");
    std::string string5;
    string3 += "pet";
    string1.append("acomb");
    string5.append(string1, 4, string1.size() - 4);

    std::cout << "\n\nAfter concatenation:\nstring1: " << string1
              << "\nstring2: " << string2 << "\nstring3: " << string3
              << "\nstring4: " << string4 << "\nstring5: " << string5 << "\n\n";

    // Demonstrating bounds safety with at() vs operator[]
    try {
        [[maybe_unused]] char ch = string3.at(100); // Throws std::out_of_range
    } catch (const std::out_of_range& ex) {
        std::cout << "Checked access: caught out_of_range exception safely.\n";
    }

    return 0;
}
